typedef struct {
    size_t len;
    unsigned char tag;              /* 0 = inline, 1 = heap */
    union {
        char buf[24];               /* inline while len <= sizeof buf */
        struct { char *ptr; size_t cap; } big;
    };
} str_t;
char *str_data(str_t *s) {
    return s->tag == 0 ? s->buf : s->big.ptr;   /* one access path */
}
